const $=id=>document.getElementById(id);
const labels={submitted:'Submitted',acknowledged:'Acknowledged',in_progress:'In progress',completed:'Completed',cancelled:'Cancelled'};
const next={submitted:['acknowledged','Acknowledge'],acknowledged:['in_progress','Start request'],in_progress:['completed','Mark completed']};
let signedIn=false,generation=0,busy=false,assistantBusy=false,confirmBusy=false,refreshQueued=false,timer,rows=[],proposal=null;
const isSample=()=>$('queueSource').value==='sample';
function setQueueMode(){const sample=isSample();$('queueTitle').textContent=sample?'Sample queue · fictional':'Confirmed demo requests';$('queueDescription').textContent=sample?'Fictional practice entries. They are never stored as passenger requests.':'Requests confirmed by passengers in active demo conversations.';$('queueNote').textContent=sample?'This sample queue is read-only and resets for the demo. No real crew action or passenger update occurs.':'Updates refresh every 10 seconds. Up to 200 requests from active demo conversations. Ending or expiring a conversation removes it from this board.';$('empty').textContent=sample?'No matching sample requests.':'No matching confirmed requests.';}
function clearProposal(){proposal=null;$('assistantProposal').hidden=true;}
function lock(){signedIn=false;generation++;clearTimeout(timer);rows=[];refreshQueued=false;clearProposal();$('requests').replaceChildren();$('board').hidden=true;$('loginForm').hidden=false;$('crewCode').value='';$('assistantQuestion').value='';$('assistantAnswer').textContent='Choose a suggestion or ask about the queue.';$('answerSource').hidden=true;$('handoverDraft').hidden=true;$('queueSource').value='confirmed';setQueueMode();}
async function api(input){const response=await fetch('/api/crew-dashboard',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const data=await response.json();if(!response.ok){if(response.status===401)lock();throw Error(data.error||'Dashboard unavailable.');}return data;}
function render(){const seat=$('seatFilter').value.trim().toUpperCase(),status=$('statusFilter').value;const visible=rows.filter(r=>(!seat||r.seat.toUpperCase().includes(seat))&&(status==='all'||(status==='active'?!['completed','cancelled'].includes(r.status):r.status===status)));$('requests').replaceChildren();$('summary').textContent=visible.length+' matching '+(isSample()?'sample':'confirmed demo')+' request'+(visible.length===1?'':'s');$('empty').hidden=visible.length!==0;for(const r of visible){const row=document.createElement('tr');const cell=text=>{const td=document.createElement('td');td.textContent=text;row.append(td);return td;};cell(r.seat);const description=cell(r.details);const category=document.createElement('small');category.textContent=r.category;description.append(category);cell(new Date(r.createdAt).toLocaleTimeString());const state=cell('');const badge=document.createElement('span');badge.className='badge';badge.textContent=labels[r.status]||r.status;state.append(badge);if(r.updatedAt){const time=document.createElement('small');time.textContent='Updated '+new Date(r.updatedAt).toLocaleTimeString();state.append(time);}const controls=cell('');if(isSample())controls.textContent='Read only';else if(next[r.status]){const [status,title]=next[r.status],button=document.createElement('button');button.textContent=title;button.disabled=busy;button.onclick=()=>update(r,status);controls.append(button);}$('requests').append(row);}}
async function load(){if(!signedIn||busy){refreshQueued=true;return;}busy=true;const mine=generation,sample=isSample();clearTimeout(timer);try{const data=await api({action:'list',sample});if(mine!==generation)return;rows=data.requests;$('status').textContent=(sample?'Sample queue':'Confirmed queue')+' refreshed '+new Date().toLocaleTimeString();}catch(e){if(mine===generation||!signedIn)$('status').textContent=e.message;}finally{busy=false;if(signedIn&&mine===generation){render();if(refreshQueued){refreshQueued=false;void load();}else if(!sample)timer=setTimeout(load,10000);}else if(signedIn&&refreshQueued){refreshQueued=false;void load();}}}
async function update(row,status){if(busy||isSample())return;busy=true;render();try{await api({action:'update',sessionId:row.sessionId,id:row.id,expectedStatus:row.status,status});$('status').textContent='Demo status updated.';}catch(e){$('status').textContent=e.message;}finally{busy=false;if(signedIn)await load();}}
async function ask(question){if(!signedIn||assistantBusy)return;assistantBusy=true;clearProposal();const mine=generation,sample=isSample();$('handoverDraft').hidden=true;$('answerSource').hidden=true;$('assistantAnswer').textContent='Checking the selected request queue…';try{const data=await api({action:'askClaude',question,sample});if(mine!==generation||!signedIn)return;const reply=typeof data.reply==='string'?data.reply:'No answer was returned.';if(data.handover){$('assistantAnswer').textContent='A draft handover is ready for crew review below.';$('handoverText').textContent=reply;$('handoverDraft').hidden=false;}else $('assistantAnswer').textContent=reply;const source=data.source==='sample'?'Sample queue · fictional':'Confirmed demo requests';const timestamp=Date.parse(data.snapshotAt);$('answerSource').textContent=source+(Number.isFinite(timestamp)?' · checked '+new Date(timestamp).toLocaleString():' · snapshot time unavailable');$('answerSource').hidden=false;proposal=!sample&&data.proposal||null;$('assistantProposal').hidden=!proposal;}catch(e){if(mine===generation)$('assistantAnswer').textContent=e.message;}finally{assistantBusy=false;}}
$('assistantForm').onsubmit=event=>{event.preventDefault();const question=$('assistantQuestion').value.trim();if(question)void ask(question);};
for(const button of document.querySelectorAll('[data-question]'))button.onclick=()=>{const question=button.dataset.question;$('assistantQuestion').value=question;void ask(question);};
$('dismissProposal').onclick=()=>{clearProposal();$('assistantAnswer').textContent='Status change dismissed. No request was changed.';};
$('confirmProposal').onclick=async()=>{if(!proposal||!signedIn||confirmBusy||isSample())return;confirmBusy=true;const selected=proposal;clearProposal();$('assistantAnswer').textContent='Confirming the selected status change…';try{await api({action:'update',sessionId:selected.sessionId,id:selected.id,expectedStatus:selected.expectedStatus,status:selected.status});$('assistantAnswer').textContent=`Seat ${selected.seat}: status updated to ${labels[selected.status]}.`;if(busy)refreshQueued=true;else await load();}catch(e){$('assistantAnswer').textContent=e.message+' Refresh the queue before trying again.';}finally{confirmBusy=false;}};
$('loginForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api({action:'login',code:$('crewCode').value});signedIn=true;generation++;$('loginForm').hidden=true;$('board').hidden=false;await load();}catch(e){$('status').textContent=e.message;}finally{$('crewCode').value='';button.disabled=false;}};
$('refresh').onclick=load;$('seatFilter').oninput=render;$('statusFilter').onchange=render;
$('queueSource').onchange=()=>{generation++;rows=[];clearProposal();$('handoverDraft').hidden=true;$('answerSource').hidden=true;$('assistantAnswer').textContent='Choose a suggestion or ask about the selected queue.';setQueueMode();render();void load();};
$('logout').onclick=async()=>{try{await api({action:'logout'});}finally{lock();$('status').textContent='Crew dashboard signed out.';}};
setQueueMode();signedIn=true;$('board').hidden=false;$('loginForm').hidden=true;void load();
